The rule is clear: cells belonging to rows or columns that are entirely one color (the line color) are recolored to 2; other cells unchanged.

```python
def transform(grid):
    R, C = len(grid), len(grid[0])
    full_rows = [r for r in range(R) if all(v == grid[r][0] for v in grid[r])]
    full_cols = [c for c in range(C) if all(grid[r][c] == grid[0][c] for r in range(R))]
    out = [row[:] for row in grid]
    for r in full_rows:
        for c in range(C):
            out[r][c] = 2
    for c in full_cols:
        for r in range(R):
            out[r][c] = 2
    return out
